// Package app assembles the process-level service dependencies.
package app

import (
	"context"
	"encoding/json"
	"errors"
	"io"
	"net/http"
	"sort"
	"strings"
	"sync"
	"time"

	"benchmark.local/iam/internal/config"
	"benchmark.local/iam/internal/domain"
	"benchmark.local/iam/internal/repository"
)

const maxJSONBodyBytes int64 = 1 << 20
const defaultPasswordResetTTL = 15 * time.Minute
const defaultEmailVerificationTTL = 24 * time.Hour
const defaultInviteTTL = 7 * 24 * time.Hour
const defaultLoginFailureThreshold = 5
const defaultLoginLockDuration = 15 * time.Minute

var errRequestBodyTooLarge = errors.New("request body too large")

// App is the assembled IAM application. Domain dependencies are added here as
// their packages are introduced by subsequent implementation tasks.
type App struct {
	Config             config.Config
	Clock              domain.Clock
	Users              *repository.UserRepository
	Organizations      *repository.OrganizationRepository
	Memberships        *repository.MembershipRepository
	Roles              *repository.RoleRepository
	Sessions           *repository.SessionRepository
	PasswordResets     *repository.PasswordResetRepository
	EmailVerifications *repository.EmailVerificationRepository
	Invites            *repository.InviteRepository
	AccessTokens       *domain.AccessTokenIssuer
	AccessValidator    *domain.AccessTokenValidator
	dummyPassword      domain.PasswordMaterial
	loginFailures      loginFailureTracker
	organizationMu     sync.Mutex
	Handler            http.Handler
}

// loginFailureTracker keeps temporary lockouts keyed by normalized identity.
// It is deliberately process-local, like the in-memory user repository.
type loginFailureTracker struct {
	mu      sync.Mutex
	entries map[string]loginFailureEntry
}

type loginFailureEntry struct {
	failures    int
	lockedUntil time.Time
}

func (t *loginFailureTracker) locked(identity string, now time.Time) bool {
	t.mu.Lock()
	defer t.mu.Unlock()
	entry, ok := t.entries[identity]
	if !ok {
		return false
	}
	if !entry.lockedUntil.IsZero() && now.Before(entry.lockedUntil) {
		return true
	}
	if !entry.lockedUntil.IsZero() {
		delete(t.entries, identity)
	}
	return false
}

func (t *loginFailureTracker) failed(identity string, now time.Time, threshold int, duration time.Duration) {
	t.mu.Lock()
	defer t.mu.Unlock()
	if t.entries == nil {
		t.entries = make(map[string]loginFailureEntry)
	}
	entry := t.entries[identity]
	entry.failures++
	if entry.failures >= threshold {
		entry.lockedUntil = now.Add(duration)
	}
	t.entries[identity] = entry
}

func (t *loginFailureTracker) succeeded(identity string) {
	t.mu.Lock()
	defer t.mu.Unlock()
	delete(t.entries, identity)
}

// New builds the application from validated configuration.
func New(cfg config.Config) *App {
	return NewWithClock(cfg, domain.RealClock{})
}

// NewWithClock assembles the application with an explicit time dependency.
// Tests and domain services can therefore use a deterministic clock.
func NewWithClock(cfg config.Config, clock domain.Clock) *App {
	if clock == nil {
		clock = domain.RealClock{}
	}
	if cfg.PasswordResetTTL <= 0 {
		cfg.PasswordResetTTL = defaultPasswordResetTTL
	}
	if cfg.EmailVerificationTTL <= 0 {
		cfg.EmailVerificationTTL = defaultEmailVerificationTTL
	}
	if cfg.InviteTTL <= 0 {
		cfg.InviteTTL = defaultInviteTTL
	}
	if cfg.LoginFailureThreshold <= 0 {
		cfg.LoginFailureThreshold = defaultLoginFailureThreshold
	}
	if cfg.LoginLockDuration <= 0 {
		cfg.LoginLockDuration = defaultLoginLockDuration
	}
	app := &App{
		Config:             cfg,
		Clock:              clock,
		Users:              repository.NewUserRepository(),
		Organizations:      repository.NewOrganizationRepository(),
		Memberships:        repository.NewMembershipRepository(),
		Roles:              repository.NewRoleRepository(),
		Sessions:           repository.NewSessionRepository(),
		PasswordResets:     repository.NewPasswordResetRepository(),
		EmailVerifications: repository.NewEmailVerificationRepository(),
		Invites:            repository.NewInviteRepository(),
		loginFailures:      loginFailureTracker{entries: make(map[string]loginFailureEntry)},
	}
	app.AccessTokens, _ = domain.NewAccessTokenIssuer(
		[]byte(cfg.HMACSecret), cfg.Issuer, cfg.AccessTTL, clock,
	)
	app.AccessValidator, _ = domain.NewAccessTokenValidator(
		[]byte(cfg.HMACSecret), cfg.Issuer, clock,
	)
	// Verify failed logins for unknown identities against the same shape of
	// password record as a real user, without retaining a user's password.
	app.dummyPassword, _ = domain.HashPassword("invalid-login-password")
	mux := http.NewServeMux()
	mux.HandleFunc("/v1/register", app.handleRegister)
	mux.HandleFunc("/v1/login", app.handleLogin)
	mux.HandleFunc("/v1/token/refresh", app.handleRefresh)
	mux.Handle("/v1/logout", app.BearerMiddleware(http.HandlerFunc(app.handleLogout)))
	mux.Handle("/v1/logout-all", app.BearerMiddleware(http.HandlerFunc(app.handleLogoutAll)))
	mux.Handle("/v1/sessions", app.BearerMiddleware(http.HandlerFunc(app.handleSessions)))
	mux.Handle("/v1/sessions/", app.BearerMiddleware(http.HandlerFunc(app.handleSession)))
	mux.Handle("/v1/password/change", app.BearerMiddleware(http.HandlerFunc(app.handlePasswordChange)))
	mux.HandleFunc("/v1/password-reset/request", app.handlePasswordResetRequest)
	mux.HandleFunc("/v1/password-reset/confirm", app.handlePasswordResetConfirm)
	mux.HandleFunc("/v1/email-verification/request", app.handleEmailVerificationRequest)
	mux.HandleFunc("/v1/email-verification/confirm", app.handleEmailVerificationConfirm)
	mux.Handle("/v1/me", app.BearerMiddleware(http.HandlerFunc(app.handleMe)))
	mux.Handle("/v1/organizations", app.BearerMiddleware(http.HandlerFunc(app.handleOrganizations)))
	mux.Handle("/v1/organizations/", app.BearerMiddleware(http.HandlerFunc(app.handleOrganizationSubresource)))
	mux.Handle("/v1/invites/", app.BearerMiddleware(http.HandlerFunc(app.handleInviteAccept)))
	app.Handler = mux
	return app
}

type accessTokenClaimsContextKey struct{}

// AccessTokenClaimsFromContext returns the verified access-token claims put in
// the request context by BearerMiddleware.
func AccessTokenClaimsFromContext(ctx context.Context) (domain.AccessTokenClaims, bool) {
	claims, ok := ctx.Value(accessTokenClaimsContextKey{}).(domain.AccessTokenClaims)
	return claims, ok
}

// BearerMiddleware validates the Authorization bearer token and passes its
// claims to the downstream handler through the request context. Authentication
// failures use one response regardless of how the credential was malformed.
func (a *App) BearerMiddleware(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		if a == nil || a.AccessValidator == nil {
			writeAPIError(w, http.StatusUnauthorized, string(domain.ErrorUnauthorized), "invalid access token")
			return
		}
		token, ok := bearerToken(r.Header.Get("Authorization"))
		if !ok {
			writeAPIError(w, http.StatusUnauthorized, string(domain.ErrorUnauthorized), "invalid access token")
			return
		}
		claims, err := a.AccessValidator.Validate(token)
		if err != nil {
			writeAPIError(w, http.StatusUnauthorized, string(domain.ErrorUnauthorized), "invalid access token")
			return
		}
		ctx := context.WithValue(r.Context(), accessTokenClaimsContextKey{}, claims)
		next.ServeHTTP(w, r.WithContext(ctx))
	})
}

func bearerToken(header string) (string, bool) {
	parts := strings.Fields(header)
	if len(parts) != 2 || !strings.EqualFold(parts[0], "Bearer") || parts[1] == "" {
		return "", false
	}
	return parts[1], true
}

func (a *App) handleMe(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodGet {
		writeAPIError(w, http.StatusMethodNotAllowed, string(domain.ErrorInvalid), "method not allowed")
		return
	}
	claims, ok := AccessTokenClaimsFromContext(r.Context())
	if !ok {
		writeAPIError(w, http.StatusUnauthorized, string(domain.ErrorUnauthorized), "invalid access token")
		return
	}
	user, err := a.Users.GetByID(domain.UserID(claims.Sub))
	if err != nil {
		writeAPIError(w, http.StatusUnauthorized, string(domain.ErrorUnauthorized), "invalid access token")
		return
	}
	writeJSON(w, http.StatusOK, dataEnvelope{Data: user.PublicProfile()})
}

type organizationCreateRequest struct {
	Name string `json:"name"`
}

// handleOrganizations serves the collection endpoint. Organization identity
// is always generated by the service; the request cannot supply a tenant ID.
func (a *App) handleOrganizations(w http.ResponseWriter, r *http.Request) {
	claims, ok := AccessTokenClaimsFromContext(r.Context())
	if !ok || a.Users == nil {
		writeAPIError(w, http.StatusUnauthorized, string(domain.ErrorUnauthorized), "invalid access token")
		return
	}
	userID := domain.UserID(claims.Sub)
	if _, err := a.Users.GetByID(userID); err != nil {
		writeAPIError(w, http.StatusUnauthorized, string(domain.ErrorUnauthorized), "invalid access token")
		return
	}

	switch r.Method {
	case http.MethodPost:
		a.createOrganization(w, r, userID)
	case http.MethodGet:
		a.listOrganizations(w, userID)
	default:
		writeAPIError(w, http.StatusMethodNotAllowed, string(domain.ErrorInvalid), "method not allowed")
	}
}

func (a *App) createOrganization(w http.ResponseWriter, r *http.Request, ownerID domain.UserID) {
	if a.Organizations == nil || a.Memberships == nil {
		writeAPIError(w, http.StatusInternalServerError, "internal", "could not create organization")
		return
	}
	var input organizationCreateRequest
	if err := decodeJSONBody(w, r, &input); err != nil {
		if errors.Is(err, errRequestBodyTooLarge) {
			writeAPIError(w, http.StatusRequestEntityTooLarge, string(domain.ErrorInvalid), "request body too large")
			return
		}
		writeAPIError(w, http.StatusBadRequest, string(domain.ErrorInvalid), "invalid request body")
		return
	}
	name := strings.TrimSpace(input.Name)
	if name == "" {
		writeAPIError(w, http.StatusBadRequest, string(domain.ErrorInvalid), "organization name is required")
		return
	}
	organizationID, err := domain.NewOrganizationID()
	if err != nil {
		writeAPIError(w, http.StatusInternalServerError, "internal", "could not create organization")
		return
	}
	now := a.Clock.Now()
	organization := domain.Organization{ID: organizationID, Name: name, OwnerID: ownerID, CreatedAt: now, UpdatedAt: now}
	if err := a.Organizations.Create(organization); err != nil {
		writeAPIError(w, http.StatusInternalServerError, "internal", "could not create organization")
		return
	}
	membershipID, err := domain.NewMembershipID()
	if err != nil {
		_ = a.Organizations.Delete(organizationID)
		writeAPIError(w, http.StatusInternalServerError, "internal", "could not create organization")
		return
	}
	membership := domain.Membership{
		ID: membershipID, OrganizationID: organizationID, UserID: ownerID,
		Role: "owner", CreatedAt: now, UpdatedAt: now,
	}
	if err := a.Memberships.Create(membership); err != nil {
		_ = a.Organizations.Delete(organizationID)
		writeAPIError(w, http.StatusInternalServerError, "internal", "could not create organization")
		return
	}
	if a.Roles != nil {
		for _, roleName := range []string{domain.RoleOwner, domain.RoleAdmin, domain.RoleViewer} {
			roleID, roleErr := domain.NewRoleID()
			role, createErr := domain.Role{}, roleErr
			if createErr == nil {
				role, createErr = domain.NewBuiltInRole(roleID, organizationID, roleName, now)
			}
			if createErr != nil || a.Roles.Create(role) != nil {
				_ = a.Memberships.Delete(membershipID)
				_ = a.Organizations.Delete(organizationID)
				writeAPIError(w, http.StatusInternalServerError, "internal", "could not create organization")
				return
			}
			if roleName == domain.RoleOwner {
				membership.RoleIDs = append(membership.RoleIDs, roleID)
				if updateErr := a.Memberships.Update(domain.Membership{ID: membershipID, OrganizationID: organizationID, UserID: ownerID, Role: domain.RoleOwner, RoleIDs: membership.RoleIDs, CreatedAt: now, UpdatedAt: now}); updateErr != nil {
					_ = a.Memberships.Delete(membershipID)
					_ = a.Organizations.Delete(organizationID)
					writeAPIError(w, http.StatusInternalServerError, "internal", "could not create organization")
					return
				}
			}
package domain

import (
	"sort"
	"strings"
	"time"
)

// Permission is an authorization capability scoped to an organization.
type Permission string

const (
	PermissionOrgRead      Permission = "org.read"
	PermissionOrgManage    Permission = "org.manage"
	PermissionMemberRead   Permission = "member.read"
	PermissionMemberManage Permission = "member.manage"
	PermissionRoleRead     Permission = "role.read"
	PermissionRoleManage   Permission = "role.manage"
	PermissionAPIKeyRead   Permission = "apikey.read"
	PermissionAPIKeyManage Permission = "apikey.manage"
	PermissionAuditRead    Permission = "audit.read"
)

const (
	RoleOwner  = "owner"
	RoleAdmin  = "admin"
	RoleViewer = "viewer"
)

var builtInPermissions = map[string][]Permission{
	RoleOwner: {
		PermissionOrgRead, PermissionOrgManage, PermissionMemberRead,
		PermissionMemberManage, PermissionRoleRead, PermissionRoleManage,
		PermissionAPIKeyRead, PermissionAPIKeyManage, PermissionAuditRead,
	},
	RoleAdmin: {
		PermissionOrgRead, PermissionOrgManage, PermissionMemberRead,
		PermissionMemberManage, PermissionRoleRead, PermissionRoleManage,
		PermissionAPIKeyRead, PermissionAPIKeyManage, PermissionAuditRead,
	},
	RoleViewer: {PermissionOrgRead, PermissionMemberRead, PermissionRoleRead},
}

// BuiltInRolePermissions returns a copy of the fixed permission set for name.
func BuiltInRolePermissions(name string) ([]Permission, bool) {
	permissions, ok := builtInPermissions[strings.ToLower(strings.TrimSpace(name))]
	if !ok {
		return nil, false
	}
	return append([]Permission(nil), permissions...), true
}

// Role describes either one of the built-in roles or an organization custom role.
type Role struct {
	ID             RoleID         `json:"id"`
	OrganizationID OrganizationID `json:"organization_id"`
	Name           string         `json:"name"`
	Permissions    []Permission   `json:"permissions"`
	BuiltIn        bool           `json:"built_in"`
	CreatedAt      time.Time      `json:"created_at"`
	UpdatedAt      time.Time      `json:"updated_at"`
}

// NewBuiltInRole creates a role with the canonical permissions for name.
func NewBuiltInRole(id RoleID, organizationID OrganizationID, name string, now time.Time) (Role, error) {
	name = strings.ToLower(strings.TrimSpace(name))
	permissions, ok := BuiltInRolePermissions(name)
	if !ok || id == "" || organizationID == "" {
		return Role{}, NewError(ErrorInvalid, "invalid built-in role")
	}
	return Role{ID: id, OrganizationID: organizationID, Name: name, Permissions: permissions, BuiltIn: true, CreatedAt: now, UpdatedAt: now}, nil
}

// ValidateRole checks organization ownership, custom permission presence, and
// that built-in roles cannot be modified into a different permission set.
func ValidateRole(role Role) error {
	if role.ID == "" || role.OrganizationID == "" || strings.TrimSpace(role.Name) == "" {
		return NewError(ErrorInvalid, "invalid role")
	}
	role.Name = strings.ToLower(strings.TrimSpace(role.Name))
	want, builtIn := BuiltInRolePermissions(role.Name)
	if role.BuiltIn != builtIn {
		return NewError(ErrorInvalid, "invalid role")
	}
	if len(role.Permissions) == 0 {
		return NewError(ErrorInvalid, "role permissions are required")
	}
	if builtIn && !samePermissions(role.Permissions, want) {
		return NewError(ErrorInvalid, "invalid built-in role permissions")
	}
	return nil
}

func samePermissions(left, right []Permission) bool {
	if len(left) != len(right) {
		return false
	}
	l := append([]Permission(nil), left...)
	r := append([]Permission(nil), right...)
	sort.Slice(l, func(i, j int) bool { return l[i] < l[j] })
	sort.Slice(r, func(i, j int) bool { return r[i] < r[j] })
	for i := range l {
		if l[i] != r[i] {
			return false
		}
	}
	return true
}
package repository

import (
	"strings"
	"sync"

	"benchmark.local/iam/internal/domain"
)

type roleKey struct {
	organizationID domain.OrganizationID
	name           string
}

// RoleRepository is a concurrency-safe organization-scoped role store.
type RoleRepository struct {
	mu        sync.RWMutex
	roles     map[domain.RoleID]domain.Role
	nameIndex map[roleKey]domain.RoleID
}

func NewRoleRepository() *RoleRepository {
	return &RoleRepository{roles: make(map[domain.RoleID]domain.Role), nameIndex: make(map[roleKey]domain.RoleID)}
}

func cloneRole(role domain.Role) domain.Role {
	role.Permissions = append([]domain.Permission(nil), role.Permissions...)
	return role
}

func (r *RoleRepository) Create(role domain.Role) error {
	if r == nil {
		return domain.NewError(domain.ErrorInvalid, "invalid role")
	}
	if err := domain.ValidateRole(role); err != nil {
		return err
	}
	key := roleKey{organizationID: role.OrganizationID, name: role.Name}
	r.mu.Lock()
	defer r.mu.Unlock()
	if _, ok := r.roles[role.ID]; ok {
		return domain.NewError(domain.ErrorConflict, "role already exists")
	}
	if _, ok := r.nameIndex[key]; ok {
		return domain.NewError(domain.ErrorConflict, "role already exists")
	}
	r.roles[role.ID] = cloneRole(role)
	r.nameIndex[key] = role.ID
	return nil
}

func (r *RoleRepository) GetByID(id domain.RoleID) (domain.Role, error) {
	if r == nil {
		return domain.Role{}, domain.ErrNotFound
	}
	r.mu.RLock()
	defer r.mu.RUnlock()
	role, ok := r.roles[id]
	if !ok {
		return domain.Role{}, domain.ErrNotFound
	}
	return cloneRole(role), nil
}

func (r *RoleRepository) GetByOrganizationAndName(organizationID domain.OrganizationID, name string) (domain.Role, error) {
	if r == nil {
		return domain.Role{}, domain.ErrNotFound
	}
	r.mu.RLock()
	defer r.mu.RUnlock()
	id, ok := r.nameIndex[roleKey{organizationID: organizationID, name: strings.ToLower(strings.TrimSpace(name))}]
	if !ok {
		return domain.Role{}, domain.ErrNotFound
	}
	return cloneRole(r.roles[id]), nil
}

func (r *RoleRepository) ListByOrganization(organizationID domain.OrganizationID) []domain.Role {
	if r == nil {
		return nil
	}
	r.mu.RLock()
	defer r.mu.RUnlock()
	result := make([]domain.Role, 0)
	for _, role := range r.roles {
		if role.OrganizationID == organizationID {
			result = append(result, cloneRole(role))
		}
	}
	return result
}
package repository

import (
	"sync"

	"benchmark.local/iam/internal/domain"
)

type membershipKey struct {
	organizationID domain.OrganizationID
	userID         domain.UserID
}

// MembershipRepository is a concurrency-safe in-memory membership store. The
// pair index and primary store are changed under one lock, making the
// organization/user uniqueness guarantee atomic under concurrent creates.
type MembershipRepository struct {
	mu          sync.RWMutex
	memberships map[domain.MembershipID]domain.Membership
	pairIndex   map[membershipKey]domain.MembershipID
}

func NewMembershipRepository() *MembershipRepository {
	return &MembershipRepository{
		memberships: make(map[domain.MembershipID]domain.Membership),
		pairIndex:   make(map[membershipKey]domain.MembershipID),
	}
}

func (r *MembershipRepository) Create(membership domain.Membership) error {
	if r == nil || membership.ID == "" || membership.OrganizationID == "" || membership.UserID == "" {
		return domain.NewError(domain.ErrorInvalid, "invalid membership")
	}
	key := membershipKey{organizationID: membership.OrganizationID, userID: membership.UserID}
	r.mu.Lock()
	defer r.mu.Unlock()
	if _, exists := r.memberships[membership.ID]; exists {
		return domain.NewError(domain.ErrorConflict, "membership already exists")
	}
	if _, exists := r.pairIndex[key]; exists {
		return domain.NewError(domain.ErrorConflict, "membership already exists")
	}
	r.memberships[membership.ID] = cloneMembership(membership)
	r.pairIndex[key] = membership.ID
	return nil
}

func (r *MembershipRepository) GetByID(id domain.MembershipID) (domain.Membership, error) {
	if r == nil {
		return domain.Membership{}, domain.ErrNotFound
	}
	r.mu.RLock()
	defer r.mu.RUnlock()
	membership, ok := r.memberships[id]
	if !ok {
		return domain.Membership{}, domain.ErrNotFound
	}
	return cloneMembership(membership), nil
}

func (r *MembershipRepository) GetByOrganizationAndUser(organizationID domain.OrganizationID, userID domain.UserID) (domain.Membership, error) {
	if r == nil {
		return domain.Membership{}, domain.ErrNotFound
	}
	r.mu.RLock()
	defer r.mu.RUnlock()
	id, ok := r.pairIndex[membershipKey{organizationID: organizationID, userID: userID}]
	if !ok {
		return domain.Membership{}, domain.ErrNotFound
	}
	return cloneMembership(r.memberships[id]), nil
}

func (r *MembershipRepository) ListByOrganization(organizationID domain.OrganizationID) []domain.Membership {
	return r.list(func(membership domain.Membership) bool { return membership.OrganizationID == organizationID })
}

func (r *MembershipRepository) ListByUser(userID domain.UserID) []domain.Membership {
	return r.list(func(membership domain.Membership) bool { return membership.UserID == userID })
}

func (r *MembershipRepository) list(matches func(domain.Membership) bool) []domain.Membership {
	if r == nil {
		return nil
	}
	r.mu.RLock()
	defer r.mu.RUnlock()
	result := make([]domain.Membership, 0)
	for _, membership := range r.memberships {
		if matches(membership) {
			result = append(result, cloneMembership(membership))
		}
	}
	return result
}

func (r *MembershipRepository) Update(membership domain.Membership) error {
	if r == nil || membership.ID == "" || membership.OrganizationID == "" || membership.UserID == "" {
		return domain.NewError(domain.ErrorInvalid, "invalid membership")
	}
	key := membershipKey{organizationID: membership.OrganizationID, userID: membership.UserID}
	r.mu.Lock()
	defer r.mu.Unlock()
	previous, exists := r.memberships[membership.ID]
	if !exists {
		return domain.ErrNotFound
	}
	if owner, claimed := r.pairIndex[key]; claimed && owner != membership.ID {
		return domain.NewError(domain.ErrorConflict, "membership already exists")
	}
	oldKey := membershipKey{organizationID: previous.OrganizationID, userID: previous.UserID}
	if oldKey != key {
		delete(r.pairIndex, oldKey)
	}
	r.memberships[membership.ID] = cloneMembership(membership)
	r.pairIndex[key] = membership.ID
	return nil
}

func cloneMembership(membership domain.Membership) domain.Membership {
	membership.RoleIDs = append([]domain.RoleID(nil), membership.RoleIDs...)
	return membership
}

func (r *MembershipRepository) Delete(id domain.MembershipID) error {
	if r == nil {
		return domain.ErrNotFound
	}
	r.mu.Lock()
	defer r.mu.Unlock()
	membership, exists := r.memberships[id]
	if !exists {
		return domain.ErrNotFound
	}
	delete(r.memberships, id)
	delete(r.pairIndex, membershipKey{organizationID: membership.OrganizationID, userID: membership.UserID})
	return nil
}
package domain

import (
	"bytes"
	"crypto/hmac"
	"crypto/sha256"
	"crypto/subtle"
	"encoding/base64"
	"encoding/json"
	"errors"
	"io"
	"time"
)

// AccessTokenClaims is the set of claims issued in an access token. Times use
// JWT NumericDate (seconds since the Unix epoch).
type AccessTokenClaims struct {
	Sub   string `json:"sub"`
	Email string `json:"email"`
	Iss   string `json:"iss"`
	Iat   int64  `json:"iat"`
	Exp   int64  `json:"exp"`
	JTI   string `json:"jti"`
}

type accessTokenHeader struct {
	Alg string `json:"alg"`
	Typ string `json:"typ"`
}

// AccessTokenIssuer creates short-lived JWT-compatible HS256 access tokens.
// The clock is injected so token lifetime behavior is deterministic for
// callers that need it to be.
type AccessTokenIssuer struct {
	secret []byte
	issuer string
	ttl    time.Duration
	clock  Clock
}

// AccessTokenValidator validates tokens issued by AccessTokenIssuer. It does
// not trust any identity or authorization data supplied by the caller: all
// claims are taken from the verified token.
type AccessTokenValidator struct {
	secret []byte
	issuer string
	clock  Clock
}

// NewAccessTokenValidator constructs a validator with the supplied signing
// key and expected issuer. The key is copied for the same reason as in the
// issuer: callers cannot mutate validator state after construction.
func NewAccessTokenValidator(secret []byte, issuer string, clock Clock) (*AccessTokenValidator, error) {
	if len(secret) == 0 || issuer == "" {
		return nil, NewError(ErrorInvalid, "invalid access token settings")
	}
	if clock == nil {
		clock = RealClock{}
	}
	return &AccessTokenValidator{
		secret: append([]byte(nil), secret...),
		issuer: issuer,
		clock:  clock,
	}, nil
}

// Validate verifies the token format, algorithm, signature, issuer and
// expiration. Every failure is returned as the same safe unauthorized error;
// token material and claim contents are deliberately not included in it.
func (v *AccessTokenValidator) Validate(token string) (AccessTokenClaims, error) {
	if v == nil || len(v.secret) == 0 || v.issuer == "" || v.clock == nil {
		return AccessTokenClaims{}, NewError(ErrorUnauthorized, "invalid access token")
	}

	parts := splitAccessToken(token)
	if parts == nil {
		return AccessTokenClaims{}, NewError(ErrorUnauthorized, "invalid access token")
	}
	headerBytes, err := base64.RawURLEncoding.DecodeString(parts[0])
	if err != nil {
		return AccessTokenClaims{}, NewError(ErrorUnauthorized, "invalid access token")
	}
	var header accessTokenHeader
	if err := decodeStrictJSON(headerBytes, &header); err != nil || header.Alg != "HS256" {
		return AccessTokenClaims{}, NewError(ErrorUnauthorized, "invalid access token")
	}

	suppliedSignature, err := base64.RawURLEncoding.DecodeString(parts[2])
	if err != nil || len(suppliedSignature) != sha256.Size {
		return AccessTokenClaims{}, NewError(ErrorUnauthorized, "invalid access token")
	}
	mac := hmac.New(sha256.New, v.secret)
	_, _ = mac.Write([]byte(parts[0] + "." + parts[1]))
	if subtle.ConstantTimeCompare(mac.Sum(nil), suppliedSignature) == 0 {
		return AccessTokenClaims{}, NewError(ErrorUnauthorized, "invalid access token")
	}

	claimsBytes, err := base64.RawURLEncoding.DecodeString(parts[1])
	if err != nil {
		return AccessTokenClaims{}, NewError(ErrorUnauthorized, "invalid access token")
	}
	var claims AccessTokenClaims
	now := v.clock.Now().Unix()
	if err := decodeStrictJSON(claimsBytes, &claims); err != nil ||
		claims.Sub == "" || claims.Email == "" || claims.Iss != v.issuer || claims.JTI == "" ||
		claims.Exp <= claims.Iat || claims.Exp <= now || claims.Iat > now {
		return AccessTokenClaims{}, NewError(ErrorUnauthorized, "invalid access token")
	}
	if _, err := ValidateEmail(claims.Email); err != nil {
		return AccessTokenClaims{}, NewError(ErrorUnauthorized, "invalid access token")
	}
	return claims, nil
}

// ValidateAccessToken is the stateless convenience form of validation.
func ValidateAccessToken(secret []byte, issuer string, now time.Time, token string) (AccessTokenClaims, error) {
	validator, err := NewAccessTokenValidator(secret, issuer, fixedClock{now: now})
	if err != nil {
		return AccessTokenClaims{}, NewError(ErrorUnauthorized, "invalid access token")
	}
	return validator.Validate(token)
}

func splitAccessToken(token string) *[3]string {
	first := -1
	second := -1
	for index, character := range token {
		if character != '.' {
			continue
		}
		if first < 0 {
			first = index
		} else {
			second = index
			break
		}
	}
	if first <= 0 || second <= first+1 || second == len(token)-1 ||
		indexOfByte(token[second+1:], '.') >= 0 {
		return nil
	}
	return &[3]string{token[:first], token[first+1 : second], token[second+1:]}
}

func indexOfByte(value string, target byte) int {
	for index := 0; index < len(value); index++ {
		if value[index] == target {
			return index
		}
	}
	return -1
}

